BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(4);

SELECT extensions.ok(
  EXISTS (
    SELECT 1
    FROM pg_catalog.pg_attribute
    WHERE attrelid = 'public.procurement_items'::regclass
      AND attname = 'estimated_total'
      AND attgenerated = 's'
      AND NOT attisdropped
  ),
  'estimated_total is generated by PostgreSQL and must be omitted from client inserts'
);

SELECT extensions.ok(
  EXISTS (
    SELECT 1
    FROM pg_catalog.pg_constraint
    WHERE conrelid = 'public.procurement_items'::regclass
      AND conname = 'procurement_items_estimated_price_source_check'
      AND pg_catalog.pg_get_constraintdef(oid) LIKE '%manual%'
      AND pg_catalog.pg_get_constraintdef(oid) LIKE '%quote_reference%'
      AND pg_catalog.pg_get_constraintdef(oid) LIKE '%approved%'
      AND pg_catalog.pg_get_constraintdef(oid) LIKE '%none%'
  ),
  'price source values match the existing procurement schema'
);

SELECT extensions.ok(
  pg_catalog.pg_get_functiondef(
    'public.fn_guard_procurement_item_estimate()'::regprocedure
  ) LIKE '%NEW.estimated_price_source%'
  AND pg_catalog.pg_get_functiondef(
    'public.fn_guard_procurement_item_estimate()'::regprocedure
  ) LIKE '%manual%',
  'client inserts use the permitted manual estimate source while official sources remain protected'
);

SELECT extensions.ok(
  EXISTS (
    SELECT 1
    FROM pg_catalog.pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'procurement_items'
      AND policyname = 'p_procurement_items_insert'
      AND with_check LIKE '%has_tenant_data_permission%'
      AND with_check LIKE '%auth.uid%'
  ),
  'procurement item inserts remain tenant-scoped and bound to the authenticated user'
);

SELECT * FROM extensions.finish();
ROLLBACK;
